}

int scan_dump(const char *path) {
  FILE *f;
  char line[160];
  int open = 0;
  int have_own = 0;

  reset_g();
  f = fopen(path, "r");
  if (!f) return 2;
  while (fgets(line, sizeof line, f)) {
    char *nl = strchr(line, '\n');
    if (nl) *nl = 0;
