#include "pick.h"
#include "store.h"

static int before(int a, int b) {
  if (b < 0) return 1;
  if (G[a].tag != G[b].tag) return G[a].tag < G[b].tag;
  if (G[a].tid != G[b].tid) return G[a].tid < G[b].tid;
  return a < b;
}

int op_pick(void) {
  PN = 0;
  for (int i = 0; i < GN; i++) G[i].done = 0;
  while (PN < GN) {
    int cur = -1;
    for (int i = 0; i < GN; i++)
      if (!G[i].done && G[i].indeg == 0 && before(i, cur)) cur = i;
    /* No releasable node means a cycle: break it at the least identity. */
    if (cur < 0)
      for (int i = 0; i < GN; i++)
        if (!G[i].done && before(i, cur)) cur = i;
    if (cur < 0) return 2;
    PLAN[PN++] = cur;
    G[cur].done = 1;
    for (int k = 0; k < nsucc[cur]; k++) {
      int j = succ[cur][k];
      if (!G[j].done && G[j].indeg > 0) G[j].indeg--;
    }
  }
  return 0;
}
