/* Compute bounded wait depth in selected order.  PLAN ordering is deliberately
   retained: op_pick already resolves equal-depth choices by identity. */
void rk_wrap(void) {
  for (int i = 0; i < GN; i++) G[i].depth = 0;
  for (int p = 0; p < PN; p++) {
    int i = PLAN[p];
    for (int k = 0; k < nsucc[i]; k++) {
      int j = succ[i][k];
      if (G[j].done && G[j].depth < G[i].depth + 1)
        G[j].depth = G[i].depth + 1;
    }
  }
}
